('tacos-de-pescado', 'Tacos de pescado', 'Una receta casera para 4 personas, lista en unos 30 minutos.', '["general", "kosher"]', 4, 30, 'facil', '[{"nombre": "Pescado tilapia", "producto": "Pescado tilapia", "cantidad": 500, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Tortillas de maíz", "producto": "Tortillas de maíz", "cantidad": 240, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Lechuga", "producto": "Lechuga", "cantidad": 150, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Crema ácida", "producto": "Crema ácida", "cantidad": 100, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Limón", "producto": "Limón", "cantidad": 200, "unidad": "g", "principal": false, "basico": false}]', '["Sazona pescado tilapia con sal, ajo y limón.", "Calienta una sartén o plancha a fuego medio alto con un poco de aceite.", "Cocina pescado tilapia hasta que esté dorado y bien cocido.", "Agrega tortillas de maíz y cocina unos minutos más.", "Sirve caliente y ajusta la sazón."]', 'publicada', NULL),
('tinga-de-pollo', 'Tinga de pollo', 'Una receta casera para 4 personas, lista en unos 35 minutos.', '["general", "kosher", "sin_gluten"]', 4, 35, 'facil', '[{"nombre": "Pechuga de pollo", "producto": "Pechuga de pollo", "cantidad": 500, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Jitomate", "producto": "Jitomate", "cantidad": 500, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Cebolla blanca", "producto": "Cebolla blanca", "cantidad": 300, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Chile jalapeño", "producto": "Chile jalapeño", "cantidad": 60, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Lechuga", "producto": "Lechuga", "cantidad": 100, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Aceite vegetal", "producto": "Aceite vegetal", "cantidad": 20, "unidad": "ml", "principal": false, "basico": true}]', '["Lava y corta jitomate en trozos pequeños.", "Calienta un poco de aceite en un sartén amplio.", "Agrega pechuga de pollo y cocina hasta que cambie de color.", "Incorpora cebolla blanca, chile jalapeño, lechuga, aceite vegetal y cocina a fuego medio hasta que todo esté tierno.", "Ajusta la sal, sirve caliente y acompaña con tortillas si lo deseas."]', 'publicada', NULL),
('tortas-de-jamon-y-queso', 'Tortas de jamón y queso', 'Una receta casera para 4 personas, lista en unos 10 minutos.', '["general"]', 4, 10, 'facil', '[{"nombre": "Pan bolillo", "producto": "Pan bolillo", "cantidad": 4, "unidad": "pza", "principal": true, "basico": false}, {"nombre": "Jamón", "producto": "Jamón", "cantidad": 200, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Queso oaxaca", "producto": "Queso oaxaca", "cantidad": 150, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Lechuga", "producto": "Lechuga", "cantidad": 100, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Jitomate", "producto": "Jitomate", "cantidad": 300, "unidad": "g", "principal": false, "basico": false}]', '["Lava y prepara los ingredientes.", "Mezcla pan bolillo con jamón, queso oaxaca en un tazón.", "Agrega lechuga, jitomate y ajusta la sazón.", "Sirve fresco o en porciones individuales."]', 'publicada', NULL),
('tortitas-de-atun', 'Tortitas de atún', 'Una receta casera para 4 personas, lista en unos 25 minutos.', '["general"]', 4, 25, 'facil', '[{"nombre": "Atún en lata", "producto": "Atún en lata", "cantidad": 2, "unidad": "pza", "principal": true, "basico": false}, {"nombre": "Huevo blanco", "producto": "Huevo blanco", "cantidad": 2, "unidad": "pza", "principal": false, "basico": false}, {"nombre": "Harina de trigo", "producto": "Harina de trigo", "cantidad": 80, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Cebolla blanca", "producto": "Cebolla blanca", "cantidad": 150, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Aceite vegetal", "producto": "Aceite vegetal", "cantidad": 30, "unidad": "ml", "principal": false, "basico": true}]', '["Sazona atún en lata con sal, ajo y limón.", "Calienta una sartén o plancha a fuego medio alto con un poco de aceite.", "Cocina atún en lata hasta que esté dorado y bien cocido.", "Agrega las verduras y cocina unos minutos más.", "Sirve caliente y ajusta la sazón."]', 'publicada', NULL),
('tortitas-de-papa-con-queso', 'Tortitas de papa con queso', 'Una receta casera para 4 personas, lista en unos 35 minutos.', '["general", "vegetariano", "kosher"]', 4, 35, 'facil', '[{"nombre": "Papa", "producto": "Papa", "cantidad": 600, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Queso fresco", "producto": "Queso fresco", "cantidad": 150, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Huevo blanco", "producto": "Huevo blanco", "cantidad": 2, "unidad": "pza", "principal": false, "basico": false}, {"nombre": "Harina de trigo", "producto": "Harina de trigo", "cantidad": 50, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Aceite vegetal", "producto": "Aceite vegetal", "cantidad": 30, "unidad": "ml", "principal": false, "basico": true}]', '["Sazona papa con sal, ajo y limón.", "Calienta una sartén o plancha a fuego medio alto con un poco de aceite.", "Cocina papa hasta que esté dorado y bien cocido.", "Agrega queso fresco y cocina unos minutos más.", "Sirve caliente y ajusta la sazón."]', 'publicada', NULL),
('tostadas-de-frijoles-y-queso', 'Tostadas de frijoles y queso', 'Una receta casera para 4 personas, lista en unos 15 minutos.', '["general", "vegetariano", "kosher"]', 4, 15, 'facil', '[{"nombre": "Tortillas de maíz", "producto": "Tortillas de maíz", "cantidad": 240, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Frijoles refritos en lata", "producto": "Frijoles refritos en lata", "cantidad": 250, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Queso fresco", "producto": "Queso fresco", "cantidad": 150, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Lechuga", "producto": "Lechuga", "cantidad": 100, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Salsa picante", "producto": "Salsa picante", "cantidad": 50, "unidad": "ml", "principal": false, "basico": true}]', '["Lava y prepara los ingredientes.", "Mezcla tortillas de maíz con frijoles refritos en lata, queso fresco en un tazón.", "Agrega lechuga, salsa picante y ajusta la sazón.", "Sirve fresco o en porciones individuales."]', 'publicada', NULL),
('tostadas-de-tinga', 'Tostadas de tinga', 'Una receta casera para 4 personas, lista en unos 30 minutos.', '["general"]', 4, 30, 'facil', '[{"nombre": "Tortillas de maíz", "producto": "Tortillas de maíz", "cantidad": 240, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Pechuga de pollo", "producto": "Pechuga de pollo", "cantidad": 400, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Jitomate", "producto": "Jitomate", "cantidad": 450, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Cebolla blanca", "producto": "Cebolla blanca", "cantidad": 150, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Crema ácida", "producto": "Crema ácida", "cantidad": 100, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Queso fresco", "producto": "Queso fresco", "cantidad": 100, "unidad": "g", "principal": false, "basico": false}]', '["Lava y prepara los ingredientes.", "Mezcla tortillas de maíz con pechuga de pollo en un tazón.", "Agrega jitomate, cebolla blanca, crema ácida, queso fresco y ajusta la sazón.", "Sirve fresco o en porciones individuales."]', 'publicada', NULL),
('te-verde-con-limon', 'Té verde con limón', 'Una receta casera para 4 personas, lista en unos 10 minutos.', '["general", "vegetariano", "diabetico", "kosher", "sin_gluten"]', 4, 10, 'facil', '[{"nombre": "Té verde", "producto": "Té verde", "cantidad": 4, "unidad": "pza", "principal": true, "basico": false}, {"nombre": "Limón", "producto": "Limón", "cantidad": 200, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Agua purificada", "producto": "Agua purificada", "cantidad": null, "unidad": "al_gusto", "principal": false, "basico": true}]', '["Lava y prepara los ingredientes.", "Mezcla té verde con agua y endulza al gusto.", "Deja reposar unos minutos y cuela si lo deseas.", "Sirve bien frío."]', 'publicada', NULL),
('yogur-con-fresas-y-avena', 'Yogur con fresas y avena', 'Una receta casera para 2 personas, lista en unos 10 minutos.', '["general", "vegetariano", "kosher"]', 2, 10, 'facil', '[{"nombre": "Yogur natural", "producto": "Yogur natural", "cantidad": 400, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Fresas", "producto": "Fresas", "cantidad": 200, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Avena", "producto": "Avena", "cantidad": 60, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Miel de abeja", "producto": "Miel de abeja", "cantidad": 15, "unidad": "g", "principal": false, "basico": true}]', '["Lava y corta fresas, avena en trozos pequeños.", "Calienta un poco de aceite en un sartén amplio.", "Agrega yogur natural y cocina hasta que cambie de color.", "Incorpora miel de abeja y cocina a fuego medio hasta que todo esté tierno.", "Ajusta la sal, sirve caliente y acompaña con tortillas si lo deseas."]', 'publicada', NULL),
('yogur-griego-con-pepino', 'Yogur griego con pepino', 'Una receta casera para 4 personas, lista en unos 10 minutos.', '["general", "vegetariano", "diabetico", "kosher", "sin_gluten"]', 4, 10, 'facil', '[{"nombre": "Yogur griego", "producto": "Yogur griego", "cantidad": 400, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Pepino", "producto": "Pepino", "cantidad": 400, "unidad": "g", "principal": true, "basico": false}, {"nombre": "Limón", "producto": "Limón", "cantidad": 100, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Ajo", "producto": "Ajo", "cantidad": 5, "unidad": "g", "principal": false, "basico": false}, {"nombre": "Aceite de oliva", "producto": "Aceite de oliva", "cantidad": 15, "unidad": "ml", "principal": false, "basico": true}]', '["Lava y prepara los ingredientes.", "Mezcla yogur griego con pepino en un tazón.", "Agrega limón, ajo, aceite de oliva y ajusta la sazón.", "Sirve fresco o en porciones individuales."]', 'publicada', NULL)
ON DUPLICATE KEY UPDATE
    nombre = VALUES(nombre),
    descripcion = VALUES(descripcion),
    tipos = VALUES(tipos),
    porciones_base = VALUES(porciones_base),
    tiempo_min = VALUES(tiempo_min),
    dificultad = VALUES(dificultad),
    ingredientes = VALUES(ingredientes),
    pasos = VALUES(pasos);

-- Conserva los videos que ya se hubieran agregado desde la pantalla anterior.
UPDATE recetas r
INNER JOIN recetas_videos v ON v.receta_slug = r.slug
SET r.video_youtube_id = v.youtube_id,
    r.video_titulo = v.titulo;
